MAX_RETRIES = 5


def send_with_retry(send, payload):
    retries = 0
    while True:
        try:
            return send(payload)
        except TimeoutError:
            if retries >= MAX_RETRIES:
                raise
            retries += 1


def retry_limit():
    return MAX_RETRIES

