import socket
import time

HOST = "127.0.0.1"
PORT = 9000
CONNECT_TIMEOUT = 3
RETRY_DELAY = 2
MAX_ATTEMPTS = 3

def connect():
    for attempt in range(MAX_ATTEMPTS):
        try:
            return socket.create_connection(
                (HOST, PORT), timeout=CONNECT_TIMEOUT
            )
        except OSError:
            if attempt == MAX_ATTEMPTS - 1:
                raise
            time.sleep(RETRY_DELAY)
